package com.carebridge.backend.partner.controller;
import com.carebridge.backend.partner.service.PartnerPerformanceService;import com.carebridge.backend.partner.dto.request.PerformanceFilter;import com.carebridge.backend.partner.dto.response.PartnerPerformanceResponse;import com.carebridge.backend.partner.exception.PartnerException;import com.carebridge.backend.common.response.ApiResponse;import com.carebridge.backend.common.util.SecurityUtils;import java.security.Principal;import java.time.LocalDate;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/partner/performance") @PreAuthorize("hasRole('PARTNER')") @RequiredArgsConstructor public class PartnerPerformanceController{private final PartnerPerformanceService service;@GetMapping public ResponseEntity<ApiResponse<PartnerPerformanceResponse>> get(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Principal principal){var filter=new PerformanceFilter(from,to);if(!filter.isValid())throw PartnerException.invalidPerformanceRange();return ResponseEntity.ok(ApiResponse.success(service.getPerformance(filter,SecurityUtils.requireCurrentUserId(principal)),"Partner performance retrieved successfully"));}}
